"""Provided figure layout for measurements generated by the learner's methods."""
from __future__ import annotations

import numpy as np
import matplotlib.pyplot as plt

from .language_data import answer_words, decode_answer

MODE_COLORS = {"joint": "#2166ac", "text-only": "#b2182b", "image-only": "#e08214", "shuffled-pairs": "#6a51a3"}


def plot_word_learning(runs):
    """Every development checkpoint for every declared seed and training mode."""
    fig, axes = plt.subplots(1, 3, figsize=(15, 4.2), sharey=True, constrained_layout=True)
    for seed, ax in zip((0, 1, 2), axes, strict=True):
        for run in runs:
            if run["seed"] != seed:
                continue
            history = run["history"]
            color = MODE_COLORS[run["mode"]]
            ax.plot([row["step"] for row in history], [row["exact_match"] for row in history],
                    ".-", label=run["mode"], color=color)
            selected = next(row for row in history if row["step"] == run["selected_step"])
            ax.scatter([selected["step"]], [selected["exact_match"]], marker="*", s=130, color=color, zorder=4)
        ax.set(title=f"Initialization seed {seed}", xlabel="Optimizer updates", ylim=(-.02, 1.02))
        ax.grid(alpha=.2)
    axes[0].set_ylabel("Development exact generated sequence")
    axes[-1].legend(fontsize=9)
    fig.suptitle("Both pixels and question words help; stars mark development-selected checkpoints")
    return fig


def plot_word_transfer(evaluation):
    """Show all seeds and all trained controls; no best-seed selection."""
    rows = evaluation["rows"] if isinstance(evaluation, dict) else evaluation
    conditions = ("familiar_solid", "familiar_muted", "compositional_muted")
    fig, axes = plt.subplots(1, 3, figsize=(15.5, 4.8), sharey=True, constrained_layout=True)
    for ax, metric, title in zip(axes, ("color_exact_match", "shape_exact_match", "caption_exact_match"),
                                 ("Color answers", "Shape answers", "Complete captions"), strict=True):
        for offset, (mode, color) in zip((-.24, -.08, .08, .24), MODE_COLORS.items(), strict=True):
            values = [[row[metric] for row in rows if row["mode"] == mode and row["condition"] == condition]
                      for condition in conditions]
            x = np.arange(3) + offset
            ax.bar(x, [np.mean(value) for value in values], width=.15, color=color, alpha=.72, label=mode)
            for xx, yy in zip(x, values, strict=True):
                ax.scatter(np.full(len(yy), xx) + np.linspace(-.025, .025, len(yy)), yy,
                           s=25, facecolors="white", edgecolors=color, zorder=3)
        ax.set(title=title, xticks=range(3), xticklabels=("Familiar\nnew images", "Familiar\nmuted colors", "Unseen pairs\nmuted colors"),
               ylim=(-.035, 1.06))
        ax.grid(axis="y", alpha=.2)
    axes[0].set_ylabel("Exact generated answer, including EOS")
    axes[-1].legend(loc="upper right", fontsize=8)
    fig.suptitle("Frozen checkpoints: strong familiar generation does not imply compositional captions\nBars average all three seeds; each white dot is one seed")
    return fig


def plot_generated_gallery(dataset, evaluation, indices, *, title, columns=3):
    """Display fixed image positions and their measured words, including failures."""
    indices = list(indices)
    rows = (len(indices) + columns - 1) // columns
    fig, axes = plt.subplots(rows, columns, figsize=(4.8 * columns, 4.3 * rows), squeeze=False,
                             constrained_layout=True)
    for ax, index in zip(axes.flat, indices):
        scene = dataset.scenes[index]
        predictions = [decode_answer(evaluation["generated_tokens"][3 * index + task]) for task in range(3)]
        truth = " ".join(answer_words(scene, "caption"))
        correct = evaluation["per_example_exact_match"][3 * index + 2]
        ax.imshow(dataset.images[index].permute(1, 2, 0))
        ax.set_title(f"Generated: {predictions[2]}\nTruth: {truth}", fontsize=11,
                     color="#2166ac" if correct else "#b2182b")
        ax.set_xlabel(f"Color answer: {predictions[0]}\nShape answer: {predictions[1]}", fontsize=10)
        ax.set_xticks([])
        ax.set_yticks([])
    for ax in list(axes.flat)[len(indices):]:
        ax.set_visible(False)
    fig.suptitle(title, fontsize=14)
    return fig


def plot_word_stage_patching(study):
    """Separate each seed/task; state joint-correct denominators explicitly."""
    conditions = ("object", "background", "unrestricted_random", "all_visual", "full_sequence")
    labels = ("Object", "Background\n8 draws", "Random\n8 draws", "All visual", "Full sequence")
    stages = study["stages"]
    fig, axes = plt.subplots(3, 2, figsize=(14, 12), constrained_layout=True)
    for seed, row_axes in enumerate(axes):
        for task, ax in zip(("color", "shape"), row_axes, strict=True):
            matrix = np.full((len(stages), len(conditions)), np.nan)
            for i, stage in enumerate(stages):
                for j, condition in enumerate(conditions):
                    records = [row["by_task"][task] for row in study["rows"]
                               if row["seed"] == seed and row["stage"] == stage and row["condition"] == condition]
                    values = [row["conditional_flip_rate"] for row in records if row["conditional_flip_rate"] is not None]
                    if values:
                        matrix[i, j] = np.mean(values)
            denominator = next(row["by_task"][task] for row in study["rows"] if row["seed"] == seed)
            shown = ax.imshow(matrix, vmin=0, vmax=1, cmap="Blues", aspect="auto")
            for i, j in np.ndindex(matrix.shape):
                value = matrix[i, j]
                ax.text(j, i, "n/a" if np.isnan(value) else f"{value:.2f}", ha="center", va="center",
                        color="white" if value > .55 else "#222222", fontsize=10)
            ax.set(xticks=range(len(conditions)), xticklabels=labels, yticks=range(len(stages)), yticklabels=stages,
                   title=f"Seed {seed} · {task}: {denominator['eligible']}/{denominator['examples']} pairs have both endpoints correct")
    fig.colorbar(shown, ax=axes, shrink=.7, label="Fraction changed to the donor answer among joint-correct pairs")
    fig.suptitle("Where can changing visual rows change generated words?\nCounterfactuals share background, geometry and sensor noise; random draws are never filtered", fontsize=14)
    return fig


def plot_word_random_patch_spread(study):
    """Display every random-region draw, including object overlaps."""
    fig, axes = plt.subplots(1, 3, figsize=(16, 4.5), sharey=True, constrained_layout=True)
    for seed, ax in enumerate(axes):
        for condition, color, offset in (("background", "#e08214", -.12), ("unrestricted_random", "#6a51a3", .12)):
            for index, stage in enumerate(study["stages"]):
                values = [row["conditional_flip_rate"] for row in study["rows"]
                          if row["seed"] == seed and row["stage"] == stage and row["condition"] == condition]
                ax.scatter(index + offset + np.linspace(-.04, .04, len(values)), values,
                           color=color, alpha=.8, label=condition if index == 0 else None)
        object_values = [next(row["conditional_flip_rate"] for row in study["rows"]
                              if row["seed"] == seed and row["stage"] == stage and row["condition"] == "object")
                         for stage in study["stages"]]
        ax.plot(range(len(object_values)), object_values, "o-", color="#2166ac", label="object")
        ax.set(title=f"Seed {seed}", xticks=range(5), xticklabels=study["stages"], ylim=(-.035, 1.04))
        ax.tick_params(axis="x", rotation=25)
        ax.grid(alpha=.2)
    axes[0].set_ylabel("Targeted flips / all joint-correct VQA pairs")
    axes[-1].legend(fontsize=8)
    fig.suptitle("All eight background and unrestricted random draws remain visible")
    return fig
